from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass

logger = BackgroundLogger.Instance()


class OtherRCOperations(AdminBaseClass):
    """Alarms"""
    def __init__(self):
        super(OtherRCOperations, self).__init__()

    def switch_ssh_service_rc(self, **kwargs):
        operation = kwargs.pop('operation')
        return getattr(self, '_{}_ssh_service'.format(operation.lower()))(**kwargs)

    def _enable_ssh_service(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.enable_ssh_service(timeout=timeout, connection=connection)

    def _disable_ssh_service(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.disable_ssh_service(timeout=timeout, connection=connection)

    def switch_ethernet_port_security_rc(self, **kwargs):
        operation = kwargs.pop('operation')
        return getattr(self, '_{}_ethernet_port_security'.format(operation.lower()))(**kwargs)

    def _enable_ethernet_port_security(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.enable_ethernet_port_security(timeout=timeout, connection=connection)

    def _disable_ethernet_port_security(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.disable_ethernet_port_security(timeout=timeout, connection=connection)